import type { TranslationsMap } from '@/lib/i18n-page';
const t: TranslationsMap = {
  en: { title: "Volunteer — Instituto Brasil Te Ama", description: "Become part of an internationally recognized humanitarian network. Register as a volunteer and contribute to real social impact initiatives in Brazil.", html: "<section class=\"hero\" style=\"min-height: 540px;\"><div class=\"hero__bg-img\" data-parallax=\"0.2\" style=\"background-image: url('/assets/hero-volunteers-hands.jpg');\"></div><div class=\"hero__veil\" style=\"background: linear-gradient(100deg, rgba(251,249,249,.95) 0%, rgba(251,249,249,.78) 45%, rgba(251,249,249,.15) 100%);\"></div><div class=\"container\"><div class=\"hero__inner\"><div class=\"eyebrow eyebrow--bordo fade-in\"> Volunteering</div><h1 class=\"hero__title fade-up delay-1\"> His presence <em>transforms.</em><br> Give your time. Earn.<br> much more in return.</h1><p class=\"hero__sub fade-up delay-2\"> Instituto Brasil Te Ama connects people to a humanitarian network with international credentials. Here, your availability finds structure, training, and recognition — either in person in Brasília or remotely. We don&#39;t require prior experience: only commitment, alignment with our values, and availability.</p><div class=\"hero__actions fade-up delay-3\"> <a href=\"#formulario\" class=\"btn btn--primary\">I want to register →</a> <a href=\"#oportunidades\" class=\"btn btn--secondary\">View opportunities ↓</a></div></div></div></section>\r\n\r\n<!-- INTRO --><section class=\"section section--white\"><div class=\"container\"><div class=\"grid\" style=\"grid-template-columns: 1fr 1.3fr; gap: 80px; align-items: center;\"><div class=\"fade-up\"> <span class=\"eyebrow\">Volunteering here</span> <h2 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 36px; line-height: 1.15; margin-bottom: 14px;\"> The volunteering that will<br> <span style=\"color: var(--bordo)\">Beyond &quot;helping&quot;.</span> </h2><hr class=\"divider\"></div><div class=\"fade-up delay-1\"><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Being a volunteer at Instituto Brasil Te Ama isn&#39;t just about showing up at an event and shaking hands. It&#39;s about becoming part of a network that operates with <strong style=\"color: var(--grafite); font-weight: 600;\">structure, responsibility, and respect for those who donate their time</strong> .</p><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Here, each volunteer has a defined role, receives guidance before acting, and is recognized for what they do. Because we believe that those who donate their time deserve to be treated with the same care that we dedicate to the causes we support. </p><div style=\"background: var(--blush); border-left: 4px solid var(--bordo); padding: 22px 28px; border-radius: 0 8px 8px 0;\"><p class=\"italic\" style=\"font-size: 17px; color: var(--grafite); line-height: 1.55;\"> You don&#39;t need prior volunteer experience to get started. You need availability, openness, and a willingness to contribute to something bigger.</p></div></div></div></div></section>\r\n\r\n<!-- COMO FUNCIONA --><section class=\"section section--alt\" id=\"como-funciona\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">From interest to action</span><h2 class=\"section-title\"> From interest to action —<br> 4 simple steps. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\" style=\"margin-top:20px;\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> ENROLLMENT</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (2 minutes)</p><p class=\"step__desc\"> Fill out the form with your profile, areas of interest, and availability. No bureaucracy, no costs.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> INTERVIEW</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (5 business days)</p><p class=\"step__desc\"> Our team will contact you by phone or video call to align expectations and understand how you can best contribute.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> TRAINING</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (1–2 hours, remote or in-person)</p><p class=\"step__desc\"> You are familiar with the network, the ongoing projects, the guidelines, and the people you will be working with.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> START</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (flexible)</p><p class=\"step__desc\"> Participate in the activities according to your schedule. After completing 30 hours of participation, you will receive the official certificate.</p></article></div></div></section>\r\n\r\n<!-- OPORTUNIDADES --><section class=\"section section--white\" id=\"oportunidades\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Opportunities</span><h2 class=\"section-title\"> 6 ways to contribute —<br> Choose the one that matches your profile. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:40px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 01 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Events and field</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Support for humanitarian events and community actions in the Federal District. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Time: 4–8 hours/month</span> <span>In-person</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 02 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Communication</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Creation of texts, photos, videos, posts and promotional materials. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duration: 4–16 hours/month.</span> <span>Remote or in-person.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 03 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Fundraising</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Identifying and approaching potential partners, companies, and NGOs. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Time: 8+ hours/month</span> <span>In-person and remote</span> </div></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 04 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Education</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Workshops, lectures and training activities for beneficiaries. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Time: 4–8 hours/month</span> <span>In-person</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 05 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Administrative</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Registration management, logistics, and administrative support. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duration: 4–16 hours/month.</span> <span>Remote or in-person.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 06 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Technology</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> IT support, websites, automation, and digital tools. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Time: 4+ hours/month</span> <span>Remote</span></div></div></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"vol-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Image of the environment — hope, hands, community, nature</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">Volunteering</span><p class=\"mood-band__quote\"> You donate your time. We provide the structure.</p></div></div></div></div></section>\r\n\r\n<!-- POR QUE SER VOLUNTÁRIO AQUI --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Volunteer here</span><h2 class=\"section-title\"> Why volunteer here? </h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:16px;font-weight:600;color:var(--grafite);\"> You offer your time. The Institute offers the network, structure, and credentials. </p></div><div class=\"grid fade-up delay-1\" style=\"grid-template-columns:0.85fr 1.15fr;gap:32px;margin-top:40px;align-items:start;\"><div class=\"card\" style=\"padding:32px;\"><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> What do you need? </p><ul style=\"list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px;\"><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Be 18 years of age or older </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Availability in the Federal District (for in-person work) or online connection (for remote work). </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Alignment with our values: transparency, respect, commitment. </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Minimum of 4 hours available per month. </li></ul><p style=\"font-size:13px;color:var(--text-gray);margin-top:18px;padding-top:16px;border-top:1px solid var(--border);font-style:italic;\"> There is no maximum — you choose how much you can give. </p></div><div><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> What do you gain? </p><div style=\"display:flex;flex-direction:column;gap:12px;\"><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Formal certificate</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Recognized by the Institute and the Knights of Malta (OSJ). This is included in his resume. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Real integration</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> You don&#39;t do freelance work — you&#39;re part of a structured network built on responsibility and respect. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Training and development</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Training in your areas of interest, with materials and contact with professionals. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Networking</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Connecting with other volunteers, NGOs, companies, and leaders of the Institute. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Documented impact</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Track exactly the difference your work makes. Periodic reports and annual evaluation.</p></div></div></div></div></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--white\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Doubts?</span><h2 class=\"section-title\"> Frequently Asked Questions<br> about volunteering. </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> Can I volunteer from another city?</summary><div class=\"faq-answer\"> Yes, we offer remote activities (communication, technology, etc.). For in-person activities, it is necessary to be located in the Federal District or surrounding area and be available to travel.</div></details><details class=\"faq-item\"><summary> My company wants to engage employees. How does it work?</summary><div class=\"faq-answer\"> Individual volunteering is for private individuals. For corporate volunteering, contact our team: atendimento@institutobrasilteama.org or (61) 3322-2535.</div></details><details class=\"faq-item\"><summary> Can I choose to work with a specific NGO?</summary><div class=\"faq-answer\"> You are joining the Institute&#39;s network. During the onboarding process, we identify the best opportunities based on your profile and the needs of our partner NGOs. Your preferences are taken into consideration.</div></details><details class=\"faq-item\"><summary> Do I receive any kind of financial compensation?</summary><div class=\"faq-answer\"> No. Volunteering at the Institute is unpaid, in accordance with Brazilian legislation on volunteering (Law 9.608/1998). What we offer in return is training, formal certification, integration into the network, and documented impact.</div></details><details class=\"faq-item\"><summary> Will I receive a certificate?</summary><div class=\"faq-answer\"> Yes. Volunteers who complete participation cycles receive a formal certificate issued by Instituto Brasil Te Ama, with institutional recognition. The certificate can be used in resumes, portfolios, and selection processes.</div></details><details class=\"faq-item\"><summary> How do I track the impact of my work?</summary><div class=\"faq-answer\"> You receive regular reports on the activities you participated in and an annual impact assessment. Each volunteer knows the difference they are making.</div></details><details class=\"faq-item\"><summary> How long will it take to receive a response after registering?</summary><div class=\"faq-answer\"> Our team will contact you within 5 business days via the email or phone number you provided. If you do not receive a message, please check your spam folder.</div></details><details class=\"faq-item\"><summary> Does the Institute have religious or political affiliation?</summary><div class=\"faq-answer\"> No. We are secular and non-partisan. We welcome volunteers of all beliefs, orientations, and backgrounds.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--alt\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Enrollment</span><h2 class=\"section-title\"> Register your application —<br> The process starts here.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:18px;\"> It takes less than 2 minutes. We will respond within 5 business days by email or phone. </p></div><div class=\"form-card fade-up\" style=\"max-width:880px;margin:0 auto;\"><form data-ms-form data-form-type=\"voluntario\"><div class=\"ms-progress\"><div class=\"ms-progress__bar\"><div class=\"ms-progress__fill\"></div></div><div class=\"ms-progress__lbl\"></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Step 1 of 2</span><h4 class=\"ms-step__title\"> Your contact details</h4></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-nome\">Full name *</label> <input class=\"form-control\" type=\"text\" id=\"v-nome\" name=\"nome\" placeholder=\"Digite seu nome completo\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-email\">Email *</label> <input class=\"form-control\" type=\"email\" id=\"v-email\" name=\"email\" placeholder=\"seu.email@exemplo.com\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-tel\">Phone / WhatsApp *</label> <input class=\"form-control\" type=\"tel\" id=\"v-tel\" name=\"telefone\" placeholder=\"(61) 98440-1100\" data-mask=\"phone\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-cidade\">City and State *</label> <input class=\"form-control\" type=\"text\" id=\"v-cidade\" name=\"cidade\" placeholder=\"Ex.: Brasília — DF\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-faixa\">Age range *</label><select class=\"form-control\" id=\"v-faixa\" name=\"faixa_etaria\" required=\"required\"><option value=\"\"> Select</option><option value=\"1818–24\"> 18–24</option><option value=\"2525–34\"> 25–34</option><option value=\"3535–44\"> 35–44</option><option value=\"4545–54\"> 45–54</option><option value=5555+> 55+</option></select><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-disp\">Availability *</label> <select class=\"form-control\" id=\"v-disp\" name=\"disponibilidade\" required=\"required\"><option value=\"\"> Select</option><option value=\"Fins de semana\"> Weekends</option><option value=\"Dias úteis\"> Business days</option><option value=\"Ambos (Fins de semana + Dias úteis)\"> Both (Weekends + Weekdays)</option><option value=\"Remoto (flexível)\"> Remote (flexible) </option></select><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-horas\">Available hours per month *</label><select class=\"form-control\" id=\"v-horas\" name=\"horas\" required=\"required\"><option value=\"\">Select</option><option value=\"Até 4h\"> Up to 4 hours</option><option value=\"44–8h\"> 4–8h</option><option value=\"88–16h\"> 8am–4pm</option><option value=16h+> 16h+</option></select><div class=\"field-msg\"></div></div></div><div class=\"ms-actions\"> <button type=\"button\" class=\"btn btn--primary\" data-ms-next=\"1\">Next →</button></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Step 2 of 2</span><h4 class=\"ms-step__title\"> Your volunteer profile</h4></div><div class=\"form-field\"> <label class=\"form-label\">Areas of interest (check one or more) *</label><div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:10px 20px;margin-top:8px;\"><label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"eventos\">Events and field</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"comunicacao\">Communication and content</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"captacao\">Institutional fundraising</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"educacao\">Education and training</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"admin\">Administrative support</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"tech\">Technology and systems</label> </div><div class=\"field-msg\"></div></div><div class=\"form-row\" style=\"margin-top:4px;\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-prof\">Education or profession <span style=\"font-weight:400;color:var(--text-gray);\">(optional)</span></label> <input class=\"form-control\" type=\"text\" id=\"v-prof\" name=\"profissao\" maxlength=\"100\" placeholder=\"Ex.: Jornalista, Desenvolvedor, Estudante de Administração\"><div class=\"field-msg\"></div></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-motivo\">Why do you want to volunteer? <span style=\"font-weight:400;color:var(--text-gray);\">(optional)</span></label> <textarea class=\"form-control\" id=\"v-motivo\" name=\"motivacao\" data-maxlen=\"500\" placeholder=\"Conte brevemente — até 500 caracteres\" style=\"height:100px;\"></textarea><div class=\"field-msg\"></div></div> <label class=\"form-checkbox-lg\"><input type=\"checkbox\" name=\"consent\" required=\"required\"><span>I have read and agree to the <a href=\"/transparencia\">Privacy Policy</a> . I understand that my data will be used exclusively for contacting me about volunteering.</span></label><div class=\"ms-actions\"> <button type=\"button\" data-ms-back=\"0\" class=\"ms-back-btn\">← Previous</button> <button type=\"submit\" class=\"btn btn--primary\">Submit application →</button> </div></div><div class=\"ms-success\"><div class=\"ms-success__icon\"><svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 class=\"ms-success__title\"> We have received your registration!</h3><p class=\"ms-success__sub\"> Our team will contact you within 5 business days by email or phone. In the meantime, learn about the projects you will be impacting.</p><div class=\"success-links\"> <a href=\"/projetos\">View projects →</a> <a href=\"/sobre\">Learn about the Institute →</a></div></div></form></div></div></section>\r\n\r\n<!-- PRÓXIMAS ETAPAS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Next steps</span><h2 class=\"section-title\"> After registration </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:36px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Your application has been received.</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Our team will contact you within 5 business days. In the meantime, learn about the projects you will be impacting.</p> <a href=\"/projetos\" class=\"btn btn--primary\">View projects →</a> </div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Want to know more about the network?</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Learn how the Institute connects volunteers, NGOs, companies, and international leaders.</p> <a href=\"/sobre\" class=\"btn btn--primary\">Get to know the Institute →</a> </div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Corporate volunteering</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Does your company want to engage employees? Talk to our team to structure a joint action plan.</p> <a href=\"/contato\" class=\"btn btn--primary\">Talk to the team →</a></div></article></div></div></section>" },
  es: { title: "Voluntario — Instituto Brasil Te Ama", description: "Forma parte de una red humanitaria reconocida internacionalmente. Regístrate como voluntario y contribuye a iniciativas de impacto social real en Brasil.", html: "<section class=\"hero\" style=\"min-height: 540px;\"><div class=\"hero__bg-img\" data-parallax=\"0.2\" style=\"background-image: url('/assets/hero-volunteers-hands.jpg');\"></div><div class=\"hero__veil\" style=\"background: linear-gradient(100deg, rgba(251,249,249,.95) 0%, rgba(251,249,249,.78) 45%, rgba(251,249,249,.15) 100%);\"></div><div class=\"container\"><div class=\"hero__inner\"><div class=\"eyebrow eyebrow--bordo fade-in\"> Voluntariado</div><h1 class=\"hero__title fade-up delay-1\"> Su presencia <em>transforma.</em><br> Dedica tu tiempo. Gana.<br> mucho más a cambio.</h1><p class=\"hero__sub fade-up delay-2\"> Instituto Brasil Te Ama conecta a personas con una red humanitaria de prestigio internacional. Aquí, tu disponibilidad encuentra estructura, capacitación y reconocimiento, ya sea presencialmente en Brasilia o de forma remota. No requerimos experiencia previa: solo compromiso, identificación con nuestros valores y disponibilidad.</p><div class=\"hero__actions fade-up delay-3\"> <a href=\"#formulario\" class=\"btn btn--primary\">Quiero registrarme →</a> <a href=\"#oportunidades\" class=\"btn btn--secondary\">Ver oportunidades ↓</a></div></div></div></section>\r\n\r\n<!-- INTRO --><section class=\"section section--white\"><div class=\"container\"><div class=\"grid\" style=\"grid-template-columns: 1fr 1.3fr; gap: 80px; align-items: center;\"><div class=\"fade-up\"> <span class=\"eyebrow\">Ser voluntario aquí</span> <h2 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 36px; line-height: 1.15; margin-bottom: 14px;\"> El voluntariado que será<br> <span style=\"color: var(--bordo)\">Más allá de &quot;ayudar&quot;.</span> </h2><hr class=\"divider\"></div><div class=\"fade-up delay-1\"><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Ser voluntario en Instituto Brasil Te Ama no se trata solo de presentarse en un evento y estrechar manos. Se trata de formar parte de una red que opera con <strong style=\"color: var(--grafite); font-weight: 600;\">estructura, responsabilidad y respeto por quienes donan su tiempo</strong> .</p><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Aquí, cada voluntario tiene un rol definido, recibe orientación antes de actuar y se le reconoce su labor. Porque creemos que quienes donan su tiempo merecen ser tratados con el mismo cuidado que nosotros dedicamos a las causas que apoyamos. </p><div style=\"background: var(--blush); border-left: 4px solid var(--bordo); padding: 22px 28px; border-radius: 0 8px 8px 0;\"><p class=\"italic\" style=\"font-size: 17px; color: var(--grafite); line-height: 1.55;\"> No necesitas experiencia previa como voluntario para empezar. Solo necesitas disponibilidad, apertura y ganas de contribuir a algo más grande.</p></div></div></div></div></section>\r\n\r\n<!-- COMO FUNCIONA --><section class=\"section section--alt\" id=\"como-funciona\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Del interés a la acción</span><h2 class=\"section-title\"> Del interés a la acción —<br> 4 sencillos pasos. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\" style=\"margin-top:20px;\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> INSCRIPCIÓN</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (2 minutos)</p><p class=\"step__desc\"> Rellena el formulario con tu perfil, áreas de interés y disponibilidad. Sin trámites burocráticos ni costes.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> ENTREVISTA</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (5 días hábiles)</p><p class=\"step__desc\"> Nuestro equipo se pondrá en contacto con usted por teléfono o videollamada para alinear las expectativas y comprender cómo puede contribuir de la mejor manera.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> CAPACITACIÓN</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (1-2 horas, a distancia o presencial)</p><p class=\"step__desc\"> Usted está familiarizado con la red, los proyectos en curso, las directrices y las personas con las que trabajará.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> COMENZAR</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (flexible)</p><p class=\"step__desc\"> Participa en las actividades según tu horario. Tras completar 30 horas de participación, recibirás el certificado oficial.</p></article></div></div></section>\r\n\r\n<!-- OPORTUNIDADES --><section class=\"section section--white\" id=\"oportunidades\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Oportunidades</span><h2 class=\"section-title\"> 6 maneras de contribuir —<br> Elige el que mejor se adapte a tu perfil. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:40px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 01 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Eventos y actividades al aire libre.</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Apoyo a eventos humanitarios y acciones comunitarias en el Distrito Federal. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duración: 4–8 horas/mes</span> <span>Presencial</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 02 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Comunicación</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Creación de textos, fotos, vídeos, publicaciones y material promocional. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duración: 4–16 horas/mes.</span> <span>Remoto o presencial.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 03 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Recaudación de fondos</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Identificar y contactar con posibles socios, empresas y ONG. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Horario: Más de 8 horas al mes.</span> <span>Presencial y remoto.</span> </div></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 04 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Educación</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Talleres, conferencias y actividades de capacitación para los beneficiarios. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duración: 4–8 horas/mes</span> <span>Presencial</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 05 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Administrativo</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Gestión de inscripciones, logística y apoyo administrativo. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Duración: 4–16 horas/mes.</span> <span>Remoto o presencial.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 06 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Tecnología</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Soporte informático, sitios web, automatización y herramientas digitales. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Tiempo: 4+ horas/mes</span> <span>Remoto</span></div></div></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"vol-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Imagen del entorno: esperanza, manos, comunidad, naturaleza</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">Voluntariado</span><p class=\"mood-band__quote\"> Tú donas tu tiempo. Nosotros proporcionamos la estructura.</p></div></div></div></div></section>\r\n\r\n<!-- POR QUE SER VOLUNTÁRIO AQUI --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Hazte voluntario aquí</span><h2 class=\"section-title\"> ¿Por qué ser voluntario aquí? </h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:16px;font-weight:600;color:var(--grafite);\"> Usted ofrece su tiempo. El Instituto ofrece la red de contactos, la estructura y las credenciales. </p></div><div class=\"grid fade-up delay-1\" style=\"grid-template-columns:0.85fr 1.15fr;gap:32px;margin-top:40px;align-items:start;\"><div class=\"card\" style=\"padding:32px;\"><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> ¿Qué necesitas? </p><ul style=\"list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px;\"><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Tener 18 años de edad o más </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilidad en el Distrito Federal (para trabajo presencial) o conexión en línea (para trabajo remoto). </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> En consonancia con nuestros valores: transparencia, respeto y compromiso. </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilidad mínima de 4 horas al mes. </li></ul><p style=\"font-size:13px;color:var(--text-gray);margin-top:18px;padding-top:16px;border-top:1px solid var(--border);font-style:italic;\"> No hay límite máximo: tú decides cuánto puedes dar. </p></div><div><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> ¿Qué ganas con ello? </p><div style=\"display:flex;flex-direction:column;gap:12px;\"><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Certificado formal</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Reconocido por el Instituto y los Caballeros de Malta (OSJ). Esto figura en su currículum. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Integración real</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> No trabajas como autónomo; formas parte de una red estructurada basada en la responsabilidad y el respeto. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Formación y desarrollo</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Formación en tus áreas de interés, con materiales y contacto con profesionales. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Redes de contactos</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Conectar con otros voluntarios, ONG, empresas y líderes del Instituto. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Impacto documentado</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Controla con precisión el impacto de tu trabajo. Informes periódicos y evaluación anual.</p></div></div></div></div></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--white\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">¿Dudas?</span><h2 class=\"section-title\"> Preguntas frecuentes<br> sobre el voluntariado. </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> ¿Puedo ser voluntario desde otra ciudad?</summary><div class=\"faq-answer\"> Sí, ofrecemos actividades a distancia (comunicación, tecnología, etc.). Para las actividades presenciales, es necesario residir en el Distrito Federal o sus alrededores y tener disponibilidad para desplazarse.</div></details><details class=\"faq-item\"><summary> Mi empresa quiere involucrar a sus empleados. ¿Cómo funciona?</summary><div class=\"faq-answer\"> El voluntariado individual es para particulares. Para voluntariado corporativo, comuníquese con nuestro equipo: atendimento@institutobrasilteama.org o al (61) 3322-2535.</div></details><details class=\"faq-item\"><summary> ¿Puedo elegir trabajar con una ONG específica?</summary><div class=\"faq-answer\"> Te unes a la red del Instituto. Durante el proceso de incorporación, identificamos las mejores oportunidades según tu perfil y las necesidades de nuestras ONG asociadas. Tus preferencias se tienen en cuenta.</div></details><details class=\"faq-item\"><summary> ¿Recibo algún tipo de compensación económica?</summary><div class=\"faq-answer\"> No. El voluntariado en el Instituto no es remunerado, de acuerdo con la legislación brasileña sobre voluntariado (Ley 9.608/1998). A cambio, ofrecemos capacitación, certificación oficial, integración a la red e impacto documentado.</div></details><details class=\"faq-item\"><summary> ¿Recibiré un certificado?</summary><div class=\"faq-answer\"> Sí. Los voluntarios que completen los ciclos de participación recibirán un certificado oficial emitido por Instituto Brasil Te Ama, con reconocimiento institucional. El certificado puede utilizarse en currículos, portafolios y procesos de selección.</div></details><details class=\"faq-item\"><summary> ¿Cómo puedo medir el impacto de mi trabajo?</summary><div class=\"faq-answer\"> Recibirás informes periódicos sobre las actividades en las que participaste y una evaluación anual de impacto. Cada voluntario sabe la diferencia que está marcando.</div></details><details class=\"faq-item\"><summary> ¿Cuánto tiempo tardaré en recibir una respuesta después de registrarme?</summary><div class=\"faq-answer\"> Nuestro equipo se pondrá en contacto con usted en un plazo de 5 días hábiles a través del correo electrónico o el número de teléfono que proporcionó. Si no recibe ningún mensaje, revise su carpeta de correo no deseado.</div></details><details class=\"faq-item\"><summary> ¿Tiene el Instituto alguna afiliación religiosa o política?</summary><div class=\"faq-answer\"> No. Somos laicos y apartidistas. Damos la bienvenida a voluntarios de todas las creencias, orientaciones y procedencias.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--alt\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Inscripción</span><h2 class=\"section-title\"> Registra tu solicitud —<br> El proceso comienza aquí.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:18px;\"> Tarda menos de 2 minutos. Le responderemos en un plazo de 5 días hábiles por correo electrónico o por teléfono. </p></div><div class=\"form-card fade-up\" style=\"max-width:880px;margin:0 auto;\"><form data-ms-form data-form-type=\"voluntario\"><div class=\"ms-progress\"><div class=\"ms-progress__bar\"><div class=\"ms-progress__fill\"></div></div><div class=\"ms-progress__lbl\"></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Paso 1 de 2</span><h4 class=\"ms-step__title\"> Sus datos de contacto</h4></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-nome\">Nombre completo *</label> <input class=\"form-control\" type=\"text\" id=\"v-nome\" name=\"nome\" placeholder=\"Digite seu nome completo\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-email\">Correo electrónico *</label> <input class=\"form-control\" type=\"email\" id=\"v-email\" name=\"email\" placeholder=\"seu.email@exemplo.com\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-tel\">Teléfono / WhatsApp *</label> <input class=\"form-control\" type=\"tel\" id=\"v-tel\" name=\"telefone\" placeholder=\"(61) 98440-1100\" data-mask=\"phone\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-cidade\">Ciudad y estado *</label> <input class=\"form-control\" type=\"text\" id=\"v-cidade\" name=\"cidade\" placeholder=\"Ex.: Brasília — DF\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-faixa\">Rango de edad *</label><select class=\"form-control\" id=\"v-faixa\" name=\"faixa_etaria\" required=\"required\"><option value=\"\"> Seleccionar</option><option value=\"1818–24\"> 18–24</option><option value=\"2525–34\"> 25–34</option><option value=\"3535–44\"> 35–44</option><option value=\"4545–54\"> 45–54</option><option value=5555+> 55+</option></select><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-disp\">Disponibilidad *</label> <select class=\"form-control\" id=\"v-disp\" name=\"disponibilidade\" required=\"required\"><option value=\"\"> Seleccionar</option><option value=\"Fins de semana\"> fines de semana</option><option value=\"Dias úteis\"> días hábiles</option><option value=\"Ambos (Fins de semana + Dias úteis)\"> Ambos (fines de semana y días laborables)</option><option value=\"Remoto (flexível)\"> Remoto (flexible) </option></select><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-horas\">Horas disponibles por mes *</label><select class=\"form-control\" id=\"v-horas\" name=\"horas\" required=\"required\"><option value=\"\">Seleccionar</option><option value=\"Até 4h\"> Hasta 4 horas</option><option value=\"44–8h\"> 4–8 horas</option><option value=\"88–16h\"> De 8:00 a 16:00.</option><option value=16h+> 16 h+</option></select><div class=\"field-msg\"></div></div></div><div class=\"ms-actions\"> <button type=\"button\" class=\"btn btn--primary\" data-ms-next=\"1\">Siguiente →</button></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Paso 2 de 2</span><h4 class=\"ms-step__title\"> Tu perfil de voluntario</h4></div><div class=\"form-field\"> <label class=\"form-label\">Áreas de interés (marque una o más) *</label><div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:10px 20px;margin-top:8px;\"><label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"eventos\">Eventos y actividades al aire libre.</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"comunicacao\">Comunicación y contenido</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"captacao\">Recaudación de fondos institucionales</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"educacao\">Educación y formación</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"admin\">Soporte administrativo</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"tech\">Tecnología y sistemas</label> </div><div class=\"field-msg\"></div></div><div class=\"form-row\" style=\"margin-top:4px;\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-prof\">Formación académica o profesión <span style=\"font-weight:400;color:var(--text-gray);\">(opcional)</span></label> <input class=\"form-control\" type=\"text\" id=\"v-prof\" name=\"profissao\" maxlength=\"100\" placeholder=\"Ex.: Jornalista, Desenvolvedor, Estudante de Administração\"><div class=\"field-msg\"></div></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-motivo\">¿Por qué quieres ser voluntario? <span style=\"font-weight:400;color:var(--text-gray);\">(opcional)</span></label> <textarea class=\"form-control\" id=\"v-motivo\" name=\"motivacao\" data-maxlen=\"500\" placeholder=\"Conte brevemente — até 500 caracteres\" style=\"height:100px;\"></textarea><div class=\"field-msg\"></div></div> <label class=\"form-checkbox-lg\"><input type=\"checkbox\" name=\"consent\" required=\"required\"><span>He leído y acepto la <a href=\"/transparencia\">Política de Privacidad</a> . Entiendo que mis datos se utilizarán exclusivamente para contactarme en relación con oportunidades de voluntariado.</span></label><div class=\"ms-actions\"> <button type=\"button\" data-ms-back=\"0\" class=\"ms-back-btn\">← Anterior</button> <button type=\"submit\" class=\"btn btn--primary\">Enviar solicitud →</button> </div></div><div class=\"ms-success\"><div class=\"ms-success__icon\"><svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 class=\"ms-success__title\"> ¡Hemos recibido su registro!</h3><p class=\"ms-success__sub\"> Nuestro equipo se pondrá en contacto con usted en un plazo de 5 días hábiles por correo electrónico o por teléfono. Mientras tanto, infórmese sobre los proyectos en los que tendrá un impacto.</p><div class=\"success-links\"> <a href=\"/projetos\">Ver proyectos →</a> <a href=\"/sobre\">Conocer el Instituto →</a></div></div></form></div></div></section>\r\n\r\n<!-- PRÓXIMAS ETAPAS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Próximos pasos</span><h2 class=\"section-title\"> Después del registro </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:36px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Su solicitud ha sido recibida.</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Nuestro equipo se pondrá en contacto con usted en un plazo de 5 días hábiles. Mientras tanto, infórmese sobre los proyectos en los que tendrá un impacto.</p> <a href=\"/projetos\" class=\"btn btn--primary\">Ver proyectos →</a> </div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> ¿Quieres saber más sobre la red?</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Descubre cómo el Instituto conecta a voluntarios, ONG, empresas y líderes internacionales.</p> <a href=\"/sobre\" class=\"btn btn--primary\">Conozca el Instituto →</a> </div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Voluntariado corporativo</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> ¿Su empresa desea motivar a sus empleados? Hable con nuestro equipo para diseñar un plan de acción conjunto.</p> <a href=\"/contato\" class=\"btn btn--primary\">Habla con el equipo →</a></div></article></div></div></section>" },
  it: { title: "Volontario — Instituto Brasil Te Ama", description: "Entra a far parte di una rete umanitaria riconosciuta a livello internazionale. Registrati come volontario e contribuisci a iniziative di reale impatto sociale in Brasile.", html: "<section class=\"hero\" style=\"min-height: 540px;\"><div class=\"hero__bg-img\" data-parallax=\"0.2\" style=\"background-image: url('/assets/hero-volunteers-hands.jpg');\"></div><div class=\"hero__veil\" style=\"background: linear-gradient(100deg, rgba(251,249,249,.95) 0%, rgba(251,249,249,.78) 45%, rgba(251,249,249,.15) 100%);\"></div><div class=\"container\"><div class=\"hero__inner\"><div class=\"eyebrow eyebrow--bordo fade-in\"> Volontariato</div><h1 class=\"hero__title fade-up delay-1\"> La sua presenza <em>trasforma.</em><br> Dedica il tuo tempo. Guadagna.<br> molto di più in cambio.</h1><p class=\"hero__sub fade-up delay-2\"> Instituto Brasil Te Ama mette in contatto le persone con una rete umanitaria di livello internazionale. Qui, la tua disponibilità trova struttura, formazione e riconoscimento, di persona a Brasilia o da remoto. Non richiediamo esperienza pregressa: solo impegno, condivisione dei nostri valori e disponibilità.</p><div class=\"hero__actions fade-up delay-3\"> <a href=\"#formulario\" class=\"btn btn--primary\">Voglio registrarmi →</a> <a href=\"#oportunidades\" class=\"btn btn--secondary\">Visualizza le opportunità ↓</a></div></div></div></section>\r\n\r\n<!-- INTRO --><section class=\"section section--white\"><div class=\"container\"><div class=\"grid\" style=\"grid-template-columns: 1fr 1.3fr; gap: 80px; align-items: center;\"><div class=\"fade-up\"> <span class=\"eyebrow\">Fare volontariato qui</span> <h2 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 36px; line-height: 1.15; margin-bottom: 14px;\"> Il volontariato che sarà<br> <span style=\"color: var(--bordo)\">Oltre l&#39;&quot;aiuto&quot;.</span> </h2><hr class=\"divider\"></div><div class=\"fade-up delay-1\"><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Essere volontario presso Instituto Brasil Te Ama non significa semplicemente presentarsi a un evento e stringere mani. Significa entrare a far parte di una rete che opera con <strong style=\"color: var(--grafite); font-weight: 600;\">struttura, responsabilità e rispetto per coloro che donano il proprio tempo</strong> .</p><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Qui, ogni volontario ha un ruolo ben definito, riceve indicazioni prima di iniziare a lavorare e viene riconosciuto per il suo impegno. Perché crediamo che chi dona il proprio tempo meriti di essere trattato con la stessa cura che dedichiamo alle cause che sosteniamo. </p><div style=\"background: var(--blush); border-left: 4px solid var(--bordo); padding: 22px 28px; border-radius: 0 8px 8px 0;\"><p class=\"italic\" style=\"font-size: 17px; color: var(--grafite); line-height: 1.55;\"> Non è necessaria alcuna esperienza pregressa di volontariato per iniziare. Servono disponibilità, apertura mentale e la volontà di contribuire a qualcosa di più grande.</p></div></div></div></div></section>\r\n\r\n<!-- COMO FUNCIONA --><section class=\"section section--alt\" id=\"como-funciona\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Dall&#39;interesse all&#39;azione</span><h2 class=\"section-title\"> Dall&#39;interesse all&#39;azione —<br> 4 semplici passaggi. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\" style=\"margin-top:20px;\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> ISCRIZIONE</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (2 minuti)</p><p class=\"step__desc\"> Compila il modulo con il tuo profilo, le aree di interesse e la disponibilità. Nessuna burocrazia, nessun costo.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> COLLOQUIO</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (5 giorni lavorativi)</p><p class=\"step__desc\"> Il nostro team ti contatterà telefonicamente o tramite videochiamata per definire le aspettative e capire come puoi dare il tuo contributo al meglio.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> FORMAZIONE</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (1-2 ore, da remoto o di persona)</p><p class=\"step__desc\"> Hai familiarità con la rete, i progetti in corso, le linee guida e le persone con cui collaborerai.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> INIZIO</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (flessibile)</p><p class=\"step__desc\"> Partecipa alle attività secondo i tuoi orari. Dopo aver completato 30 ore di partecipazione, riceverai l&#39;attestato ufficiale.</p></article></div></div></section>\r\n\r\n<!-- OPORTUNIDADES --><section class=\"section section--white\" id=\"oportunidades\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Opportunità</span><h2 class=\"section-title\"> 6 modi per contribuire —<br> Scegli quello che meglio si adatta al tuo profilo. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:40px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 01 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Eventi e campo</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Sostegno a eventi umanitari e iniziative comunitarie nel Distretto Federale. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Durata: 4–8 ore/mese</span> <span>In presenza</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 02 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Comunicazione</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Creazione di testi, foto, video, post e materiale promozionale. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Durata: 4-16 ore al mese.</span> <span>Da remoto o in presenza.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 03 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Raccolta fondi</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Individuare e contattare potenziali partner, aziende e ONG. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Tempo: 8+ ore/mese</span> <span>In presenza e da remoto</span> </div></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 04 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Preparazione</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Workshop, conferenze e attività formative per i beneficiari. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Tempo: 4–8 ore/mese</span> <span>In presenza</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 05 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Amministrativo</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Gestione delle iscrizioni, logistica e supporto amministrativo. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Durata: 4-16 ore al mese.</span> <span>Da remoto o in presenza.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 06 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Tecnologia</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Supporto IT, siti web, automazione e strumenti digitali. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Tempo: 4+ ore/mese</span> <span>Lavoro da remoto</span></div></div></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"vol-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Immagine dell&#39;ambiente: speranza, mani, comunità, natura</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">Volontariato</span><p class=\"mood-band__quote\"> Tu offri il tuo tempo. Noi forniamo la struttura.</p></div></div></div></div></section>\r\n\r\n<!-- POR QUE SER VOLUNTÁRIO AQUI --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Diventa volontario qui</span><h2 class=\"section-title\"> Perché fare volontariato qui? </h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:16px;font-weight:600;color:var(--grafite);\"> Tu offri il tuo tempo. L&#39;Istituto offre la rete, la struttura e le credenziali. </p></div><div class=\"grid fade-up delay-1\" style=\"grid-template-columns:0.85fr 1.15fr;gap:32px;margin-top:40px;align-items:start;\"><div class=\"card\" style=\"padding:32px;\"><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> Di che cosa hai bisogno? </p><ul style=\"list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px;\"><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Avere almeno 18 anni </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilità nel Distretto Federale (per il lavoro in presenza) o connessione online (per il lavoro da remoto). </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Allineamento con i nostri valori: trasparenza, rispetto, impegno. </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilità minima di 4 ore al mese. </li></ul><p style=\"font-size:13px;color:var(--text-gray);margin-top:18px;padding-top:16px;border-top:1px solid var(--border);font-style:italic;\"> Non c&#39;è un limite massimo: sei tu a scegliere quanto donare. </p></div><div><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> Che cosa ci guadagni? </p><div style=\"display:flex;flex-direction:column;gap:12px;\"><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Certificato formale</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Riconosciuto dall&#39;Istituto e dai Cavalieri di Malta (OSJ). Tale riconoscimento è incluso nel suo curriculum vitae. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Integrazione reale</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Non lavori come freelance, ma fai parte di una rete strutturata basata su responsabilità e rispetto. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Formazione e sviluppo</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Formazione nei vostri ambiti di interesse, con materiali didattici e contatto con professionisti del settore. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Reti</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Creare connessioni con altri volontari, ONG, aziende e leader dell&#39;Istituto. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Impatto documentato</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Monitora con precisione l&#39;impatto del tuo lavoro. Report periodici e valutazione annuale.</p></div></div></div></div></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--white\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Dubbi?</span><h2 class=\"section-title\"> Domande frequenti<br> Informazioni sul volontariato. </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> Posso fare volontariato da un&#39;altra città?</summary><div class=\"faq-answer\"> Sì, offriamo attività a distanza (comunicazione, tecnologia, ecc.). Per le attività in presenza, è necessario risiedere nel Distretto Federale o nelle zone limitrofe ed essere disponibili a spostarsi.</div></details><details class=\"faq-item\"><summary> La mia azienda desidera coinvolgere i dipendenti. Come si fa?</summary><div class=\"faq-answer\"> Il volontariato individuale è riservato ai privati cittadini. Per il volontariato aziendale, contattate il nostro team: atendimento@institutobrasilteama.org o (61) 3322-2535.</div></details><details class=\"faq-item\"><summary> Posso scegliere di collaborare con una ONG specifica?</summary><div class=\"faq-answer\"> Entrerete a far parte della rete dell&#39;Istituto. Durante il processo di onboarding, individueremo le migliori opportunità in base al vostro profilo e alle esigenze delle nostre ONG partner. Le vostre preferenze saranno prese in considerazione.</div></details><details class=\"faq-item\"><summary> Riceverò un qualche tipo di compenso finanziario?</summary><div class=\"faq-answer\"> No. Il volontariato presso l&#39;Istituto non è retribuito, in conformità con la legislazione brasiliana sul volontariato (Legge 9.608/1998). In cambio offriamo formazione, certificazione ufficiale, integrazione nella rete e un impatto documentato.</div></details><details class=\"faq-item\"><summary> Riceverò un certificato?</summary><div class=\"faq-answer\"> Sì. I volontari che completano i cicli di partecipazione ricevono un certificato ufficiale rilasciato da Instituto Brasil Te Ama, con riconoscimento istituzionale. Il certificato può essere utilizzato nei curriculum vitae, nei portfolio e nei processi di selezione.</div></details><details class=\"faq-item\"><summary> Come posso monitorare l&#39;impatto del mio lavoro?</summary><div class=\"faq-answer\"> Riceverai resoconti periodici sulle attività a cui hai partecipato e una valutazione annuale dell&#39;impatto. Ogni volontario sa di poter fare la differenza.</div></details><details class=\"faq-item\"><summary> Quanto tempo ci vorrà per ricevere una risposta dopo la registrazione?</summary><div class=\"faq-answer\"> Il nostro team ti contatterà entro 5 giorni lavorativi tramite l&#39;indirizzo email o il numero di telefono che ci hai fornito. Se non ricevi alcun messaggio, controlla la cartella spam.</div></details><details class=\"faq-item\"><summary> L&#39;Istituto ha affiliazioni religiose o politiche?</summary><div class=\"faq-answer\"> No. Siamo laici e apartitici. Accogliamo volontari di ogni credo, orientamento e provenienza.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--alt\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Iscrizione</span><h2 class=\"section-title\"> Registra la tua candidatura —<br> Il processo inizia qui.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:18px;\"> Ci vogliono meno di 2 minuti. Ti risponderemo entro 5 giorni lavorativi via email o telefono. </p></div><div class=\"form-card fade-up\" style=\"max-width:880px;margin:0 auto;\"><form data-ms-form data-form-type=\"voluntario\"><div class=\"ms-progress\"><div class=\"ms-progress__bar\"><div class=\"ms-progress__fill\"></div></div><div class=\"ms-progress__lbl\"></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Passo 1 di 2</span><h4 class=\"ms-step__title\"> I tuoi dati di contatto</h4></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-nome\">Nome e cognome *</label> <input class=\"form-control\" type=\"text\" id=\"v-nome\" name=\"nome\" placeholder=\"Digite seu nome completo\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-email\">E-mail *</label> <input class=\"form-control\" type=\"email\" id=\"v-email\" name=\"email\" placeholder=\"seu.email@exemplo.com\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-tel\">Telefono / WhatsApp *</label> <input class=\"form-control\" type=\"tel\" id=\"v-tel\" name=\"telefone\" placeholder=\"(61) 98440-1100\" data-mask=\"phone\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-cidade\">Città e Stato *</label> <input class=\"form-control\" type=\"text\" id=\"v-cidade\" name=\"cidade\" placeholder=\"Ex.: Brasília — DF\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-faixa\">Fascia d&#39;età *</label><select class=\"form-control\" id=\"v-faixa\" name=\"faixa_etaria\" required=\"required\"><option value=\"\"> Selezionare</option><option value=\"1818–24\"> 18–24</option><option value=\"2525–34\"> 25–34</option><option value=\"3535–44\"> 35–44</option><option value=\"4545–54\"> 45–54</option><option value=5555+> 55+</option></select><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-disp\">Disponibilità *</label> <select class=\"form-control\" id=\"v-disp\" name=\"disponibilidade\" required=\"required\"><option value=\"\"> Selezionare</option><option value=\"Fins de semana\"> Fine settimana</option><option value=\"Dias úteis\"> Giorni lavorativi</option><option value=\"Ambos (Fins de semana + Dias úteis)\"> Entrambi (fine settimana + giorni feriali)</option><option value=\"Remoto (flexível)\"> Remoto (flessibile) </option></select><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-horas\">Ore disponibili al mese*</label><select class=\"form-control\" id=\"v-horas\" name=\"horas\" required=\"required\"><option value=\"\">Selezionare</option><option value=\"Até 4h\"> Fino a 4 ore</option><option value=\"44–8h\"> 4–8 ore</option><option value=\"88–16h\"> dalle 8:00 alle 16:00</option><option value=16h+> 16 ore e oltre</option></select><div class=\"field-msg\"></div></div></div><div class=\"ms-actions\"> <button type=\"button\" class=\"btn btn--primary\" data-ms-next=\"1\">Avanti →</button></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Fase 2 di 2</span><h4 class=\"ms-step__title\"> Il tuo profilo di volontariato</h4></div><div class=\"form-field\"> <label class=\"form-label\">Aree di interesse (selezionare una o più opzioni) *</label><div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:10px 20px;margin-top:8px;\"><label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"eventos\">Eventi e campo</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"comunicacao\">Comunicazione e contenuti</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"captacao\">Raccolta fondi istituzionale</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"educacao\">Istruzione e formazione</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"admin\">Supporto amministrativo</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"tech\">Tecnologia e sistemi</label> </div><div class=\"field-msg\"></div></div><div class=\"form-row\" style=\"margin-top:4px;\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-prof\">Istruzione o professione <span style=\"font-weight:400;color:var(--text-gray);\">(facoltativo)</span></label> <input class=\"form-control\" type=\"text\" id=\"v-prof\" name=\"profissao\" maxlength=\"100\" placeholder=\"Ex.: Jornalista, Desenvolvedor, Estudante de Administração\"><div class=\"field-msg\"></div></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-motivo\">Perché vuoi fare volontariato? <span style=\"font-weight:400;color:var(--text-gray);\">(facoltativo)</span></label> <textarea class=\"form-control\" id=\"v-motivo\" name=\"motivacao\" data-maxlen=\"500\" placeholder=\"Conte brevemente — até 500 caracteres\" style=\"height:100px;\"></textarea><div class=\"field-msg\"></div></div> <label class=\"form-checkbox-lg\"><input type=\"checkbox\" name=\"consent\" required=\"required\"><span>Ho letto e accetto l&#39; <a href=\"/transparencia\">Informativa sulla privacy</a> . Comprendo che i miei dati saranno utilizzati esclusivamente per contattarmi in merito al volontariato.</span></label><div class=\"ms-actions\"> <button type=\"button\" data-ms-back=\"0\" class=\"ms-back-btn\">← Precedente</button> <button type=\"submit\" class=\"btn btn--primary\">Invia la domanda →</button> </div></div><div class=\"ms-success\"><div class=\"ms-success__icon\"><svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 class=\"ms-success__title\"> Abbiamo ricevuto la tua registrazione!</h3><p class=\"ms-success__sub\"> Il nostro team ti contatterà entro 5 giorni lavorativi via e-mail o telefono. Nel frattempo, scopri di più sui progetti a cui contribuirai.</p><div class=\"success-links\"> <a href=\"/projetos\">Visualizza i progetti →</a> <a href=\"/sobre\">Scopri di più sull&#39;Istituto →</a></div></div></form></div></div></section>\r\n\r\n<!-- PRÓXIMAS ETAPAS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Prossimi passi</span><h2 class=\"section-title\"> Dopo la registrazione </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:36px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> La tua candidatura è stata ricevuta.</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Il nostro team ti contatterà entro 5 giorni lavorativi. Nel frattempo, scopri di più sui progetti a cui contribuirai.</p> <a href=\"/projetos\" class=\"btn btn--primary\">Visualizza i progetti →</a> </div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Vuoi saperne di più sulla rete?</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Scopri come l&#39;Istituto mette in contatto volontari, ONG, aziende e leader internazionali.</p> <a href=\"/sobre\" class=\"btn btn--primary\">Scopri l&#39;Istituto →</a> </div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Volontariato aziendale</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> La vostra azienda desidera coinvolgere i dipendenti? Contattate il nostro team per elaborare un piano d&#39;azione congiunto.</p> <a href=\"/contato\" class=\"btn btn--primary\">Parla con il team →</a></div></article></div></div></section>" },
  fr: { title: "Bénévole — Instituto Brasil Te Ama", description: "Rejoignez un réseau humanitaire internationalement reconnu. Inscrivez-vous comme bénévole et contribuez à des initiatives à impact social concret au Brésil.", html: "<section class=\"hero\" style=\"min-height: 540px;\"><div class=\"hero__bg-img\" data-parallax=\"0.2\" style=\"background-image: url('/assets/hero-volunteers-hands.jpg');\"></div><div class=\"hero__veil\" style=\"background: linear-gradient(100deg, rgba(251,249,249,.95) 0%, rgba(251,249,249,.78) 45%, rgba(251,249,249,.15) 100%);\"></div><div class=\"container\"><div class=\"hero__inner\"><div class=\"eyebrow eyebrow--bordo fade-in\"> Volontariat</div><h1 class=\"hero__title fade-up delay-1\"> Sa présence <em>transforme.</em><br> Donnez de votre temps. Gagnez.<br> et bien plus encore en retour.</h1><p class=\"hero__sub fade-up delay-2\"> Instituto Brasil Te Ama met en relation des personnes avec un réseau humanitaire reconnu internationalement. Ici, votre disponibilité est encadrée, encadrée par des formations et valorisée, que ce soit en présentiel à Brasília ou à distance. Aucune expérience préalable n&#39;est requise : seuls l&#39;engagement, l&#39;adhésion à nos valeurs et votre disponibilité sont essentiels.</p><div class=\"hero__actions fade-up delay-3\"> <a href=\"#formulario\" class=\"btn btn--primary\">Je souhaite m&#39;inscrire →</a> <a href=\"#oportunidades\" class=\"btn btn--secondary\">Voir les opportunités ↓</a></div></div></div></section>\r\n\r\n<!-- INTRO --><section class=\"section section--white\"><div class=\"container\"><div class=\"grid\" style=\"grid-template-columns: 1fr 1.3fr; gap: 80px; align-items: center;\"><div class=\"fade-up\"> <span class=\"eyebrow\">Bénévolat ici</span> <h2 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 36px; line-height: 1.15; margin-bottom: 14px;\"> Le bénévolat qui<br> <span style=\"color: var(--bordo)\">Au-delà de « l&#39;aide ».</span> </h2><hr class=\"divider\"></div><div class=\"fade-up delay-1\"><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Être bénévole chez Instituto Brasil Te Ama, ce n&#39;est pas seulement participer à un événement et serrer des mains. C&#39;est intégrer un réseau <strong style=\"color: var(--grafite); font-weight: 600;\">structuré, responsable et respectueux de ceux qui donnent de leur temps</strong> .</p><p style=\"font-size: 17px; color: var(--text-gray); line-height: 1.85; margin-bottom: 18px;\"> Ici, chaque bénévole a un rôle précis, reçoit des instructions avant d&#39;agir et est reconnu pour son engagement. Car nous croyons que ceux qui donnent de leur temps méritent le même respect que celui que nous portons aux causes que nous soutenons. </p><div style=\"background: var(--blush); border-left: 4px solid var(--bordo); padding: 22px 28px; border-radius: 0 8px 8px 0;\"><p class=\"italic\" style=\"font-size: 17px; color: var(--grafite); line-height: 1.55;\"> Aucune expérience de bénévolat préalable n&#39;est requise pour commencer. Il vous faut simplement être disponible, ouvert d&#39;esprit et avoir la volonté de contribuer à un projet plus vaste.</p></div></div></div></div></section>\r\n\r\n<!-- COMO FUNCIONA --><section class=\"section section--alt\" id=\"como-funciona\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">De l&#39;intérêt à l&#39;action</span><h2 class=\"section-title\"> De l&#39;intérêt à l&#39;action —<br> 4 étapes simples. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\" style=\"margin-top:20px;\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> INSCRIPTION</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (2 minutes)</p><p class=\"step__desc\"> Remplissez le formulaire avec votre profil, vos domaines d&#39;intérêt et vos disponibilités. Sans paperasse, sans frais.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> ENTRETIEN</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (5 jours ouvrables)</p><p class=\"step__desc\"> Notre équipe vous contactera par téléphone ou par appel vidéo afin de définir les attentes et de comprendre comment vous pouvez au mieux contribuer.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> ENTRAÎNEMENT</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (1 à 2 heures, à distance ou en présentiel)</p><p class=\"step__desc\"> Vous connaissez le réseau, les projets en cours, les directives et les personnes avec lesquelles vous travaillerez.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> COMMENCER</h3><p style=\"font-size:13px;font-weight:600;color:var(--bordo);margin:-6px 0 8px;\"> (flexible)</p><p class=\"step__desc\"> Participez aux activités selon votre emploi du temps. Après 30 heures de participation, vous recevrez le certificat officiel.</p></article></div></div></section>\r\n\r\n<!-- OPORTUNIDADES --><section class=\"section section--white\" id=\"oportunidades\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Opportunités</span><h2 class=\"section-title\"> 6 façons de contribuer —<br> Choisissez celui qui correspond à votre profil. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:40px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 01 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Événements et terrain</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Soutien aux actions humanitaires et communautaires dans le District fédéral. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Temps : 4 à 8 heures par mois</span> <span>en présentiel</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 02 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Communication</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Création de textes, photos, vidéos, publications et supports promotionnels. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Durée : 4 à 16 heures par mois.</span> <span>À distance ou en présentiel.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 03 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> collecte de fonds</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Identifier et approcher les partenaires, entreprises et ONG potentiels. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Temps : 8 heures et plus par mois,</span> <span>en présentiel et à distance</span> </div></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 04 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Éducation</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Ateliers, conférences et activités de formation pour les bénéficiaires. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Temps : 4 à 8 heures par mois</span> <span>en présentiel</span> </div></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 05 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Administratif</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Gestion des inscriptions, logistique et soutien administratif. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Durée : 4 à 16 heures par mois.</span> <span>À distance ou en présentiel.</span> </div></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:28px 26px;\"><div style=\"font-family:var(--font-lora);font-weight:700;font-size:26px;color:var(--dourado);line-height:1;margin-bottom:12px;\"> 06 </div><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:17px;letter-spacing:.5px;text-transform:uppercase;margin-bottom:10px;\"> Technologie</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.65;margin-bottom:14px;\"> Assistance informatique, sites web, automatisation et outils numériques. </p><div style=\"display:flex;flex-direction:column;gap:4px;padding-top:12px;border-top:1px solid var(--border);font-size:13px;color:var(--bordo);font-weight:600;\"> <span>Temps : 4 heures et plus par mois</span> <span>à distance</span></div></div></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"vol-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Image de l&#39;environnement — espoir, mains, communauté, nature</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">Volontariat</span><p class=\"mood-band__quote\"> Vous donnez de votre temps. Nous fournissons la structure.</p></div></div></div></div></section>\r\n\r\n<!-- POR QUE SER VOLUNTÁRIO AQUI --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Devenez bénévole ici</span><h2 class=\"section-title\"> Pourquoi faire du bénévolat ici ? </h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:16px;font-weight:600;color:var(--grafite);\"> Vous offrez votre temps. L&#39;Institut offre le réseau, la structure et les qualifications. </p></div><div class=\"grid fade-up delay-1\" style=\"grid-template-columns:0.85fr 1.15fr;gap:32px;margin-top:40px;align-items:start;\"><div class=\"card\" style=\"padding:32px;\"><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> De quoi avez-vous besoin? </p><ul style=\"list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:12px;\"><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Avoir 18 ans ou plus </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilité dans le District fédéral (pour le travail en présentiel) ou connexion en ligne (pour le télétravail). </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> En accord avec nos valeurs : transparence, respect, engagement. </li><li style=\"display:flex;gap:10px;align-items:flex-start;font-size:14px;color:var(--grafite);line-height:1.55;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Disponibilité minimale de 4 heures par mois. </li></ul><p style=\"font-size:13px;color:var(--text-gray);margin-top:18px;padding-top:16px;border-top:1px solid var(--border);font-style:italic;\"> Il n&#39;y a pas de maximum — vous choisissez combien vous pouvez donner. </p></div><div><p style=\"font-size:13px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--bordo);margin-bottom:18px;\"> Qu&#39;y gagnez-vous ? </p><div style=\"display:flex;flex-direction:column;gap:12px;\"><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">certificat officiel</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Reconnu par l&#39;Institut et l&#39;Ordre des Chevaliers de Malte (OSJ). Cette reconnaissance figure dans son CV. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Intégration réelle</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Vous ne travaillez pas en freelance — vous faites partie d&#39;un réseau structuré, fondé sur la responsabilité et le respect. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Formation et développement</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Formation dans vos domaines d&#39;intérêt, avec du matériel pédagogique et des contacts avec des professionnels. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Réseautage</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Établir des liens avec d&#39;autres bénévoles, des ONG, des entreprises et les dirigeants de l&#39;Institut. </p></div></div><div style=\"display:flex;gap:12px;align-items:flex-start;padding:16px 18px;background:var(--white);border:1px solid var(--border);border-radius:8px;\"> <span style=\"flex-shrink:0;color:var(--bordo);margin-top:2px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink:0;\"><polyline points=\"20 6 9 17 4 12\"/></svg></span><div> <strong style=\"font-size:14px;color:var(--grafite);font-weight:600;\">Impact documenté</strong><p style=\"font-size:13px;color:var(--text-gray);line-height:1.55;margin-top:2px;\"> Mesurez précisément l&#39;impact de votre travail. Rapports périodiques et évaluation annuelle.</p></div></div></div></div></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--white\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Des doutes ?</span><h2 class=\"section-title\"> Foire aux questions<br> à propos du bénévolat. </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> Puis-je faire du bénévolat depuis une autre ville ?</summary><div class=\"faq-answer\"> Oui, nous proposons des activités à distance (communication, technologie, etc.). Pour les activités en présentiel, il est nécessaire de résider dans le District fédéral ou ses environs et d&#39;être disponible pour se déplacer.</div></details><details class=\"faq-item\"><summary> Mon entreprise souhaite impliquer ses employés. Comment cela fonctionne-t-il ?</summary><div class=\"faq-answer\"> Le bénévolat individuel est réservé aux particuliers. Pour le bénévolat en entreprise, veuillez contacter notre équipe : atendimento@institutobrasilteama.org ou (61) 3322-2535.</div></details><details class=\"faq-item\"><summary> Puis-je choisir de travailler avec une ONG spécifique ?</summary><div class=\"faq-answer\"> Vous intégrez le réseau de l&#39;Institut. Lors de votre intégration, nous identifions les opportunités les plus adaptées à votre profil et aux besoins de nos ONG partenaires. Vos préférences sont prises en compte.</div></details><details class=\"faq-item\"><summary> Vais-je recevoir une quelconque compensation financière ?</summary><div class=\"faq-answer\"> Non. Le bénévolat à l&#39;Institut n&#39;est pas rémunéré, conformément à la législation brésilienne sur le bénévolat (loi 9.608/1998). En contrepartie, nous proposons une formation, une certification officielle, l&#39;intégration au réseau et un impact mesurable.</div></details><details class=\"faq-item\"><summary> Vais-je recevoir un certificat ?</summary><div class=\"faq-answer\"> Oui. Les bénévoles qui terminent un cycle de participation reçoivent un certificat officiel délivré par Instituto Brasil Te Ama, bénéficiant d&#39;une reconnaissance institutionnelle. Ce certificat peut être utilisé dans un CV, un portfolio ou lors d&#39;un processus de sélection.</div></details><details class=\"faq-item\"><summary> Comment puis-je mesurer l&#39;impact de mon travail ?</summary><div class=\"faq-answer\"> Vous recevez des rapports réguliers sur les activités auxquelles vous avez participé, ainsi qu&#39;une évaluation annuelle de leur impact. Chaque bénévole prend conscience de l&#39;influence positive qu&#39;il exerce.</div></details><details class=\"faq-item\"><summary> Combien de temps faut-il pour recevoir une réponse après l&#39;inscription ?</summary><div class=\"faq-answer\"> Notre équipe vous contactera dans les 5 jours ouvrables par courriel ou par téléphone aux coordonnées que vous avez fournies. Si vous ne recevez pas de message, veuillez vérifier votre dossier de courriers indésirables.</div></details><details class=\"faq-item\"><summary> L&#39;Institut a-t-il une affiliation religieuse ou politique ?</summary><div class=\"faq-answer\"> Non. Nous sommes laïques et apolitiques. Nous accueillons des bénévoles de toutes convictions, orientations et origines.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--alt\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Inscription</span><h2 class=\"section-title\"> Enregistrez votre candidature —<br> Le processus commence ici.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top:18px;\"> Cela prend moins de 2 minutes. Nous vous répondrons dans les 5 jours ouvrables par courriel ou par téléphone. </p></div><div class=\"form-card fade-up\" style=\"max-width:880px;margin:0 auto;\"><form data-ms-form data-form-type=\"voluntario\"><div class=\"ms-progress\"><div class=\"ms-progress__bar\"><div class=\"ms-progress__fill\"></div></div><div class=\"ms-progress__lbl\"></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Étape 1 sur 2</span><h4 class=\"ms-step__title\"> Vos coordonnées</h4></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-nome\">Nom et prénom *</label> <input class=\"form-control\" type=\"text\" id=\"v-nome\" name=\"nome\" placeholder=\"Digite seu nome completo\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-email\">E-mail *</label> <input class=\"form-control\" type=\"email\" id=\"v-email\" name=\"email\" placeholder=\"seu.email@exemplo.com\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-tel\">Téléphone / WhatsApp *</label> <input class=\"form-control\" type=\"tel\" id=\"v-tel\" name=\"telefone\" placeholder=\"(61) 98440-1100\" data-mask=\"phone\" required=\"required\"><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-cidade\">Ville et État *</label> <input class=\"form-control\" type=\"text\" id=\"v-cidade\" name=\"cidade\" placeholder=\"Ex.: Brasília — DF\" required=\"required\"><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-faixa\">Tranche d&#39;âge *</label><select class=\"form-control\" id=\"v-faixa\" name=\"faixa_etaria\" required=\"required\"><option value=\"\"> Sélectionner</option><option value=\"1818–24\"> 18–24</option><option value=\"2525–34\"> 25–34</option><option value=\"3535–44\"> 35–44</option><option value=\"4545–54\"> 45–54</option><option value=5555+> 55 ans et plus</option></select><div class=\"field-msg\"></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-disp\">Disponibilité *</label> <select class=\"form-control\" id=\"v-disp\" name=\"disponibilidade\" required=\"required\"><option value=\"\"> Sélectionner</option><option value=\"Fins de semana\"> Week-ends</option><option value=\"Dias úteis\"> jours ouvrables</option><option value=\"Ambos (Fins de semana + Dias úteis)\"> Les deux (week-ends + jours de semaine)</option><option value=\"Remoto (flexível)\"> Télétravail (flexible) </option></select><div class=\"field-msg\"></div></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-horas\">Heures disponibles par mois *</label><select class=\"form-control\" id=\"v-horas\" name=\"horas\" required=\"required\"><option value=\"\">Sélectionner</option><option value=\"Até 4h\"> Jusqu&#39;à 4 heures</option><option value=\"44–8h\"> 4 à 8 h</option><option value=\"88–16h\"> 8h-16h</option><option value=16h+> 16h+</option></select><div class=\"field-msg\"></div></div></div><div class=\"ms-actions\"> <button type=\"button\" class=\"btn btn--primary\" data-ms-next=\"1\">Suivant →</button></div></div><div class=\"ms-step\"><div class=\"ms-step__head\"> <span class=\"ms-step__eyebrow\">Étape 2 sur 2</span><h4 class=\"ms-step__title\"> Votre profil de bénévole</h4></div><div class=\"form-field\"> <label class=\"form-label\">Domaines d&#39;intérêt (cochez une ou plusieurs cases) *</label><div style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:10px 20px;margin-top:8px;\"><label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"eventos\">Événements et terrain</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"comunicacao\">Communication et contenu</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"captacao\">Collecte de fonds institutionnelle</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"educacao\">Éducation et formation</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"admin\">soutien administratif</label> <label class=\"lead-opt\"><input type=\"checkbox\" name=\"areas\" value=\"tech\">Technologie et systèmes</label> </div><div class=\"field-msg\"></div></div><div class=\"form-row\" style=\"margin-top:4px;\"><div class=\"form-field\"> <label class=\"form-label\" for=\"v-prof\">Formation ou profession <span style=\"font-weight:400;color:var(--text-gray);\">(facultatif)</span></label> <input class=\"form-control\" type=\"text\" id=\"v-prof\" name=\"profissao\" maxlength=\"100\" placeholder=\"Ex.: Jornalista, Desenvolvedor, Estudante de Administração\"><div class=\"field-msg\"></div></div></div><div class=\"form-field\"> <label class=\"form-label\" for=\"v-motivo\">Pourquoi souhaitez-vous faire du bénévolat ? <span style=\"font-weight:400;color:var(--text-gray);\">(facultatif)</span></label> <textarea class=\"form-control\" id=\"v-motivo\" name=\"motivacao\" data-maxlen=\"500\" placeholder=\"Conte brevemente — até 500 caracteres\" style=\"height:100px;\"></textarea><div class=\"field-msg\"></div></div> <label class=\"form-checkbox-lg\"><input type=\"checkbox\" name=\"consent\" required=\"required\"><span>J&#39;ai lu et j&#39;accepte la <a href=\"/transparencia\">politique de confidentialité</a> . Je comprends que mes données seront utilisées exclusivement pour me contacter au sujet du bénévolat.</span></label><div class=\"ms-actions\"> <button type=\"button\" data-ms-back=\"0\" class=\"ms-back-btn\">← Précédent</button> <button type=\"submit\" class=\"btn btn--primary\">Soumettre une candidature →</button> </div></div><div class=\"ms-success\"><div class=\"ms-success__icon\"><svg width=\"30\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#059669\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 class=\"ms-success__title\"> Nous avons bien reçu votre inscription !</h3><p class=\"ms-success__sub\"> Notre équipe vous contactera par courriel ou par téléphone dans un délai de 5 jours ouvrables. En attendant, découvrez les projets auxquels vous contribuerez.</p><div class=\"success-links\"> <a href=\"/projetos\">Voir les projets →</a> <a href=\"/sobre\">En savoir plus sur l&#39;Institut →</a></div></div></form></div></div></section>\r\n\r\n<!-- PRÓXIMAS ETAPAS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Prochaines étapes</span><h2 class=\"section-title\"> Après l&#39;inscription </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns:repeat(3,1fr);gap:24px;margin-top:36px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Votre candidature a été reçue.</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Notre équipe vous contactera dans les 5 jours ouvrables. En attendant, découvrez les projets auxquels vous contribuerez.</p> <a href=\"/projetos\" class=\"btn btn--primary\">Voir les projets →</a> </div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> Vous souhaitez en savoir plus sur le réseau ?</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Découvrez comment l&#39;Institut met en relation bénévoles, ONG, entreprises et dirigeants internationaux.</p> <a href=\"/sobre\" class=\"btn btn--primary\">Découvrez l&#39;Institut →</a> </div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding:30px 28px;display:flex;flex-direction:column;height:100%;\"><h3 style=\"font-family:var(--font-lora);font-weight:700;font-size:19px;margin-bottom:10px;\"> bénévolat en entreprise</h3><p style=\"font-size:14px;color:var(--text-gray);line-height:1.7;margin-bottom:22px;flex:1;\"> Votre entreprise souhaite mobiliser ses employés ? Contactez notre équipe pour élaborer un plan d’action commun.</p> <a href=\"/contato\" class=\"btn btn--primary\">Parlez à l&#39;équipe →</a></div></article></div></div></section>" },
};
export default t;
